module TopModule (
    input clk,
    input reset,
    input [7:0] d,
    output reg [7:0] q
);

    // Declare 8 D flip-flops with active high synchronous reset
    reg [7:0] q0, q1, q2, q3, q4, q5, q6, q7;

    // Assign output to the first DFF
    assign q = q0;

    // Synchronous reset with active high
    always @(posedge clk) begin
        if (reset) begin
            q0 <= 8'b0;
            q1 <= 8'b0;
            q2 <= 8'b0;
            q3 <= 8'b0;
            q4 <= 8'b0;
            q5 <= 8'b0;
            q6 <= 8'b0;
            q7 <= 8'b0;
        end else begin
            q0 <= d[0];
            q1 <= d[1];
            q2 <= d[2];
            q3 <= d[3];
            q4 <= d[4];
            q5 <= d[5];
            q6 <= d[6];
            q7 <= d[7];
