        if (reset) begin
            q0 <= 8'h34;
            q1 <= 8'h34;
            q2 <= 8'h34;
            q3 <= 8'h34;
            q4 <= 8'h34;
            q5 <= 8'h34;
            q6 <= 8'h34;
            q7 <= 8'h34;
        end else begin
            // Update all flip-flops with the input data
            q0 <= d[0];
            q1 <= d[1];
            q2 <= d[2];
            q3 <= d[3];
            q4 <= d[4];
            q5 <= d[5];
            q6 <= d[6];
