        if (k)
            Q <= ~Q;
        else
            Q <= 1'b0;
    end
    else begin
        if (k)
            Q <= 1'b1;
        else
            Q <= Q;
    end
end

endmodule

module TopModule (
    input a,
    input b,
    input c,
    input d,
    output out
);
    // The Karnaugh map is represented as a 4-bit truth table
    // with the following values:
    // 00: 1
    // 01: 1
    // 11: 1
    // 10: 0
    // The resulting logic expression is:
    // out = (a & b) | (c & d)
    assign out = (a & b) | (c & d);
endmodule

module TopModule (
