);

    // Assign statement implementation
    assign out_assign = a ^ b;

    // Combinational always block implementation
    always @(*) begin
        out_always_comb = a ^ b;
    end

    // Clocked always block implementation with flip-flop delay
    reg out_ff;
    always @(posedge clk) begin
        out_ff <= a ^ b;
    end
    assign out_always_ff = out_ff;

endmodule

