module TopModule (
    input  p1a,
    input  p1b,
    input  p1c,
    input  p1d,
    input  p2a,
    input  p2b,
    input  p2c,
    input  p2d,
    output p1y,
    output p2y
);

    // 7420-style 4-input NAND gate
    wire nand1_out;
    wire nand2_out;

    // First NAND gate
    nand (nand1_out, p1a, p1b, p1c, p1d);

    // Second NAND gate
    nand (nand2_out, p2a, p2b, p2c, p2d);

    // Combine outputs to get final outputs
    or (p1y, nand1_out, nand2_out);
    or (p2y, nand1_out, nand2_out);

endmodule

module TopModule (
    input clk,
    input reset,
    output reg [2:0] ena,
    output reg [15:0] q
);

always @(posedge clk) begin
    if (reset) begin
        ena <= 3'b0;
        q <= 16'b0;
    end else begin
        // Update the enable signals for each digit
        ena[0] <= (q[3:0] == 4'b1111);
        ena[1] <= (q[7:4] == 4'b1111);
        ena[2] <= (q[11:8] == 4'b1111);
        ena[3] <= (q[15:12] == 4'b1111);

        // Update the counter values
        q <= q + 16'b1;
    end
end

endmodule

