module TopModule (
    input  mode,
    input  too_cold,
    input  too_hot,
    input  fan_on,
    output heater,
    output aircon,
    output fan
);

    // Heater and air conditioner control logic
    assign heater = mode ? (too_cold ? 1'b1 : 1'b0) : 1'b0;
    assign aircon = mode ? (too_hot ? 1'b1 : 1'b0) : 1'b0;

    // Fan control logic
    assign fan = (heater | aircon) ? 1'b1 : (fan_on ? 1'b1 : 1'b0);

endmodule

module TopModule (
    input clk,
    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output reg [15:0] q
);

    // 16 D flip-flops with byte-enable control
    reg [7:0] q0, q1, q2, q3, q4, q5, q6, q7;
    reg [7:0] q8, q9, q10, q11, q12, q13, q14, q15;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            q0 <= 8'b0;
            q1 <= 8'b0;
            q2 <= 8'b0;
            q3 <= 8'b0;
            q4 <= 8'b0;
            q5 <= 8'b0;
            q6 <= 8'b0;
            q7 <= 8'b0;
            q8 <= 8'b0;
            q9 <= 8'b0;
            q10 <= 8'b0;
            q11 <= 8'b0;
            q12 <= 8'b0;
            q13 <= 8'b0;
            q14 <= 8'b0;
            q15 <= 8'b0;
        end else begin
            // Update each byte of the 16-bit registers based on byteena
            q0 <= (byteena[1]) ? d[15:8] : q0;
            q1 <= (byteena[1]) ? d[15:8] : q1;
            q2 <= (byteena[1]) ? d[15:8] : q2;
            q3 <= (byteena[1]) ? d[15:8] : q3;
            q4 <= (byteena[1]) ? d[15:8] : q4;
            q5 <= (byteena[1]) ? d[15:8] : q5;
            q6 <= (byteena[1]) ? d[15:8] : q6;
            q7 <= (byteena[1]) ? d[15:8] : q7;
            q8 <= (byteena[1]) ? d[15:8] : q8;
            q9 <= (byteena[1]) ? d[15:8] : q9;
            q10 <= (byteena[1]) ? d[15:8] : q10;
            q11 <= (byteena[1]) ? d[15:8] : q11;
            q12 <= (byteena[1]) ? d[15:8] : q12;
            q13 <= (byteena[1]) ? d[15:8] : q13;
            q14 <= (byteena[1]) ? d[15:8] : q14;
            q15 <= (byteena[1]) ? d[15:8] : q15;
        end
    end

    // Combine the 16-bit registers into a single 16-bit output
    assign q = {q15, q14, q13, q12, q11, q10, q9, q8, q7, q6, q5, q4, q3, q2, q1, q0};

endmodule

module TopModule (
    input clk,
    input x,
    output z
);

// Declare three flip-flops with asynchronous reset
reg f1, f2, f3;

// Declare three two-input gates
wire xor_out, and_out, or_out;

// XOR gate: x ^ f1
xor (xor_out, x, f1);

// AND gate: x & ~f1
and (and_out, x, ~f1);

// OR gate: x | ~f1
or (or_out, x, ~f1);

// NOR gate: ~(x | f1 | ~f1 | f2 | ~f2 | f3 | ~f3)
nor (z, x, f1, ~f1, f2, ~f2, f3, ~f3);

// Update flip-flops on positive clock edge
always @(posedge clk) begin
    f1 <= x;
    f2 <= ~f1;
    f3 <= ~f2;
end

endmodule

module TopModule (
    input a,
    input b,
    input c,
    input d,
    output out,
    output out_n
);

    // Intermediate wires for AND gates
    wire and_a_b;
    wire and_c_d;

    // First layer: AND gates
    and and_gate_a_b (and_a_b, a, b);
    and and_gate_c_d (and_c_d, c, d);

    // Second layer: OR gate
    or or_gate (out, and_a_b, and_c_d);

    // Inverted output
    not not_gate (out_n, out);

endmodule

