module TopModule (
    input clk,
    input load,
    input [9:0] data,
    output tc
);

reg [9:0] counter;

always @(posedge clk) begin
    if (load) begin
        counter <= data;
    end else begin
        counter <= counter - 1;
    end
end

assign tc = (counter == 10'b0);

endmodule

module TopModule (
    input p1a,
    input p1b,
    input p1c,
    input p1d,
    input p1e,
    input p1f,
    input p2a,
    input p2b,
    input p2c,
    input p2d,
    output p1y,
    output p2y
);

    // Intermediate wires for AND gates
    wire and1_out, and2_out, and3_out, and4_out;

    // First AND gate: p1a, p1b, p1c
    assign and1_out = p1a & p1b & p1c;

    // Second AND gate: p1d, p1e, p1f
    assign and2_out = p1d & p1e & p1f;

    // OR of the two AND gates
    assign p1y = and1_out | and2_out;

    // Second AND gate: p2a, p2b
    assign and3_out = p2a & p2b;

    // Second AND gate: p2c, p2d
    assign and4_out = p2c & p2d;

    // OR of the two AND gates
    assign p2y = and3_out | and4_out;

endmodule

module TopModule (
    input clk,
    input reset,
    output reg [31:0] q
);

// Galois LFSR with taps at bit positions 32, 22, 2, and 1
always @(posedge clk) begin
    if (reset) begin
        q <= 32'h1;
    end else begin
        q <= {q[30:0], q[0]} ^ {32'b0, q[32], q[22], q[2], q[1]};
    end
end

endmodule

module TopModule (
