always @(*) begin
    case (state)
        2'b00: next_state = x ? 2'b01 : 2'b00;
        2'b01: next_state = x ? 2'b10 : 2'b00;
        2'b10: next_state = x ? 2'b11 : 2'b00;
        2'b11: next_state = x ? 2'b00 : 2'b00;
        default: next_state = 2'b00;
    endcase
end

// Count logic
always @(*) begin
    case (state)
        2'b00: next_count = count + 1;
        2'b01: next_count = count + 1;
        2'b10: next_count = count + 1;
        2'b11: next_count = count + 1;
        default: next_count = 2'b00;
    endcase
end

// Output logic
always @(*) begin
    case (state)
        2'b00: z = ~x;
        2'b01: z = ~x;
        2'b10: z = ~x;
