    localparam FOUND = 2'b10;

    reg [1:0] current_state;
    reg [1:0] next_state;

    // State transition logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (data == 1'b1)
                    next_state = SEARCH;
                else
                    next_state = IDLE;
            end
            SEARCH: begin
                if (data == 1'b1)
                    next_state = SEARCH;
                else
                    next_state = FOUND;
            end
            FOUND: begin
                next_state = FOUND;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                start_shifting = 1'b0;
            end
            SEARCH: begin
                start_shifting = 1'b0;
