module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

// Update the game state on the positive clock edge
always @(posedge clk) begin
    if (load) begin
        q <= data;
    end else begin
        // Update each cell based on its neighbours
        for (int i = 0; i < 16; i++) begin
            for (int j = 0; j < 16; j++) begin
                // Calculate the number of neighbours
                int neighbours = 0;
                if (i > 0) neighbours += q[i-1][j];
                if (i < 15) neighbours += q[i+1][j];
                if (j > 0) neighbours += q[i][j-1];
                if (j < 15) neighbours += q[i][j+1];
                if (i == 0 && j == 0) neighbours += q[15][15];
                if (i == 0 && j == 15) neighbours += q[15][0];
                if (i == 15 && j == 0) neighbours += q[0][15];
                if (i == 15 && j == 15) neighbours += q[0][0];

                // Update the cell based on the number of neighbours
                if (neighbours == 0 || neighbours == 1) begin
                    q[i][j] <= 0;
                end else if (neighbours == 2) begin
                    q[i][j] <= q[i][j];
                end else if (neighbours == 3) begin
                    q[i][j] <= 1;
                end else begin
                    q[i][j] <= 0;
                end
            end
        end
    end
end

endmodule

